use appic_dex::rlp_decoder::RlpDecoder;

fn main() {
    let encoded_data = hex::decode("").unwrap();
    
    let quote = RlpDecoder::decode_cross_chain_data(&encoded_data).unwrap();
    
    println!("Success: {}", quote.success);
    if let Some(error) = &quote.error {
        println!("Error: {}", error);
    }
    
    if let Some(data) = &quote.data {
        println!("Decoded CrossChainQuote:");
        println!("  Amount In: {}", data.total_amount_in);
        println!("  Amount Out: {}", data.total_amount_out);
        println!("  Min Amount Out: {:?}", data.total_min_amount_out);
        println!("  Slippage: {:?}", data.total_slippage);
        println!("  Steps: {}", data.steps.len());
        
        for (i, step) in data.steps.iter().enumerate() {
            println!("    Step {}: Chain {} - {} -> {}", i, step.chain_id, step.amount_in, step.amount_out);
            println!("      Route: {} hops", step.route.len());
            for (j, hop) in step.route.iter().enumerate() {
                println!("        Hop {}: {} -> {} (fee: {})", j, hop.sell_token, hop.buy_token, hop.fee);
            }
            println!("      QSwap Data: {:?}", step.qswap_data.is_some());
        }
    }
}